package edu.bjfu.eldercare;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.web.servlet.MockMvc;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.transaction.PlatformTransactionManager;import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.time.*;
import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"app.jobs=false"}) @AutoConfigureMockMvc @TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class DatabaseIntegrationTest {
 @Autowired Store d;@Autowired CareService service;@Autowired Auth auth;@Autowired MockMvc mvc;@Autowired PlatformTransactionManager tm;
 Auth.User admin=new Auth.User(1,"admin1","ADMIN",1,1L);Auth.User family=new Auth.User(2,"family1","FAMILY",1,1L);
 void rollback(Runnable r){new TransactionTemplate(tm).execute(s->{s.setRollbackOnly();r.run();return null;});}
 void reject(Runnable r){assertThrows(RuntimeException.class,()->new TransactionTemplate(tm).execute(s->{r.run();return null;}));}
 @Test @Order(1) void everyTableHasTwentyRows(){for(var t:d.rows("SHOW FULL TABLES WHERE Table_type='BASE TABLE'")){String name=t.values().iterator().next().toString();assertTrue(d.count("SELECT COUNT(*) FROM `"+name+"`")>=20,name);}}
 @Test void fifteenViewsExecute(){var views=d.rows("SHOW FULL TABLES WHERE Table_type='VIEW'");assertTrue(views.size()>=15);for(var v:views)d.rows("SELECT * FROM "+v.values().iterator().next()+" LIMIT 3");}
 @Test void fifteenQueryPairsAreEquivalent()throws Exception{var queries=new ObjectMapper().readTree(Files.readString(Path.of("database/queries.json")));assertEquals(15,queries.size());for(var q:queries){var a=d.rows(q.get("a").asText());var b=d.rows(q.get("b").asText());assertEquals(canonical(a),canonical(b),q.get("id").asText());}}
 String canonical(List<Map<String,Object>> rows){return rows.stream().map(m->m.values().stream().map(x->x==null?"NULL":x.toString()).toList().toString()).sorted().toList().toString();}
 @Test void duplicateIdentityRejected(){reject(()->d.update("INSERT INTO elder(name,identity_hash,identity_cipher,birth_date,address,community_id) SELECT name,identity_hash,identity_cipher,birth_date,address,community_id FROM elder WHERE id=1"));}
 @Test void danglingForeignKeyRejected(){reject(()->d.update("INSERT INTO elder_tag(elder_id,tag) VALUES(999999,'ALONE')"));}
 @Test void overlappingPlanRejected(){reject(()->d.update("INSERT INTO care_plan(assessment_id,bundle_id,caregiver_id,starts_at,ends_at) SELECT assessment_id,bundle_id,caregiver_id,starts_at,ends_at FROM v_plan_context WHERE id=1"));}
 @Test void assessmentCannotBelongToAnotherElder(){reject(()->service.execute(admin,"plan.create",Map.of("elderId",1,"assessmentId",2,"bundleId",1,"caregiverId",1,"startsAt",LocalDateTime.now().plusDays(100).toString(),"endsAt",LocalDateTime.now().plusDays(101).toString())));}
 @Test void overlappingShiftRejected(){reject(()->d.update("INSERT INTO shift(caregiver_id,starts_at,ends_at,capacity) SELECT caregiver_id,starts_at,ends_at,capacity FROM shift WHERE id=2"));}
 @Test void shiftCapacityCheck(){reject(()->d.update("UPDATE shift SET used_count=capacity+1 WHERE id=2"));}
 @Test void confirmationRequired(){reject(()->d.update("UPDATE service_order SET status='COMPLETED' WHERE id=2"));}
 @Test void validDispatchAndHistory(){rollback(()->{service.execute(admin,"order.assign",Map.of("orderId",2,"shiftId",2,"reason","首次测试"));service.execute(admin,"order.assign",Map.of("orderId",2,"shiftId",2,"reason","重新安排时间"));assertEquals(2,d.count("SELECT COUNT(*) FROM v_dispatch_context WHERE order_id=2"));assertEquals(1,d.count("SELECT COUNT(*) FROM v_dispatch_context WHERE order_id=2 AND active_order IS NOT NULL"));assertEquals(1,d.count("SELECT used_count FROM shift WHERE id=2"));});}
 @Test void wrongAreaOrCertificateRejected(){reject(()->service.execute(admin,"order.assign",Map.of("orderId",2,"shiftId",4,"reason","无资格护工")));assertEquals("PENDING",d.one("SELECT status FROM service_order WHERE id=2").get("status"));}
 @Test void expiredAssessmentStopsDispatch(){rollback(()->{d.update("UPDATE assessment SET valid_until=NOW()-INTERVAL 1 SECOND WHERE id=1");assertThrows(RuntimeException.class,()->d.call("assign_order",2,2,"过期测试"));d.call("expire_plans");assertEquals("PAUSED",d.one("SELECT status FROM v_plan_context WHERE id=1").get("status"));});}
 @Test void expiredCredentialRejected(){rollback(()->{d.update("UPDATE credential SET valid_until=NOW()-INTERVAL 1 SECOND WHERE id=1");assertThrows(RuntimeException.class,()->d.call("assign_order",2,2,"证书过期"));});}
 @Test void rectificationBlocksDispatch(){rollback(()->{d.update("UPDATE inspection SET status='OPEN' WHERE id=1");assertThrows(RuntimeException.class,()->d.call("assign_order",2,2,"整改测试"));});}
 @Test void immutableCompletedOrder(){reject(()->d.update("UPDATE service_order SET amount=0 WHERE id=1"));}
 @Test void historicalDeleteForbidden(){reject(()->d.update("DELETE FROM attendance WHERE id=1"));}
 @Test void deviceRebindPreservesOldOwner(){rollback(()->{d.update("UPDATE device_binding SET unbound_at=NOW() WHERE id=1");d.insert("INSERT INTO device_binding(device_id,elder_id,bound_at) VALUES(1,2,NOW())");assertEquals(1,d.count("SELECT b.elder_id FROM vital v JOIN device_binding b ON b.id=v.binding_id WHERE v.id=1"));});}
 @Test void sampleOutsideBindingRejected(){reject(()->d.update("INSERT INTO vital(binding_id,metric_rule_id,sample_key,collected_at,metric_value,source) VALUES(1,1,'before-bind',NOW()-INTERVAL 365 DAY,50,'TEST')"));}
 @Test void duplicateSampleRejected(){reject(()->d.update("INSERT INTO vital(binding_id,metric_rule_id,sample_key,collected_at,metric_value,source) SELECT binding_id,metric_rule_id,sample_key,collected_at,metric_value,source FROM vital WHERE id=1"));}
 @Test void thresholdCreatesPendingEvent(){rollback(()->{long n=d.count("SELECT COUNT(*) FROM emergency");d.insert("INSERT INTO vital(binding_id,metric_rule_id,sample_key,collected_at,metric_value,source) VALUES(1,1,'abnormal-test',NOW(),100,'TEST')");assertEquals(n+1,d.count("SELECT COUNT(*) FROM emergency"));});}
 @Test void escalationIsIdempotent(){rollback(()->{d.update("UPDATE emergency SET deadline=NOW()-INTERVAL 1 SECOND WHERE id=1");d.call("escalate_events");d.call("escalate_events");assertEquals(2,d.count("SELECT level FROM emergency WHERE id=1"));assertEquals(1,d.count("SELECT COUNT(*) FROM emergency_log WHERE event_id=1 AND level=2"));});}
 @Test void claimInvalidOrderRollsBack(){long before=d.count("SELECT COUNT(*) FROM claim");reject(()->d.call("submit_claim",1,1,"2099-01","[2,999999]"));assertEquals(before,d.count("SELECT COUNT(*) FROM claim"));}
 @Test void duplicateClaimRejectedAcrossPolicy(){String month=d.one("SELECT period FROM claim WHERE id=1").get("period").toString();reject(()->d.update("INSERT INTO claim(elder_id,item_id,period) VALUES(1,1,?)",month));}
 @Test void paymentIsImmutable(){reject(()->d.update("UPDATE claim SET status='DRAFT' WHERE id=1"));}
 @Test void familyCannotReadOtherElder(){assertThrows(Forbidden.class,()->service.elderScope(family,2));}
 @Test void regulatorCannotCreateOrder(){assertThrows(Forbidden.class,()->service.execute(new Auth.User(6,"regulator1","REGULATOR",1,1L),"order.create",Map.of()));}
 @Test void sessionRequired()throws Exception{mvc.perform(get("/api/data/elders")).andExpect(status().isUnauthorized());}
 @Test void familyRowsAreScopedAndNoSensitiveFields()throws Exception{String token=(String)auth.login("family1",System.getenv("DEMO_PASSWORD")).get("token");String text=mvc.perform(get("/api/data/elders").header("Authorization","Bearer "+token)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();var body=new ObjectMapper().readTree(text);assertEquals(1,body.get("total").asInt());assertFalse(text.contains("identity_cipher"));assertFalse(text.contains("identity_hash"));}
 @Test void maliciousLoginDoesNotBypass(){assertThrows(Rule.class,()->auth.login("' OR 1=1 --","anything"));}
 @Test void logoutRevokesSession(){String token=(String)auth.login("family1",System.getenv("DEMO_PASSWORD")).get("token");auth.logout("Bearer "+token);assertThrows(Unauthorized.class,()->auth.require("Bearer "+token));}
 @Test void serviceCompletionRequiresReviewAndConfirmation(){rollback(()->{service.execute(admin,"order.assign",Map.of("orderId",2,"shiftId",2,"reason","流程测试"));var worker=new Auth.User(3,"caregiver1","CAREGIVER",1,1L);service.execute(worker,"order.accept",Map.of("orderId",2));service.execute(worker,"order.checkin",Map.of("orderId",2,"location","模拟圈外","fenceOk",false));long dispatch=d.count("SELECT id FROM v_dispatch_context WHERE active_order=2");d.update("UPDATE attendance SET check_in=NOW()-INTERVAL 60 MINUTE WHERE dispatch_id=?",dispatch);service.execute(worker,"order.finish",Map.of("orderId",2,"notes","完整流程测试"));long attendance=d.count("SELECT id FROM attendance WHERE dispatch_id=?",dispatch);assertEquals("REVIEW",d.one("SELECT status FROM attendance WHERE id=?",attendance).get("status"));service.execute(new Auth.User(4,"manager1","MANAGER",1,1L),"hours.review",Map.of("attendanceId",attendance,"approve",true,"reason","核对演示服务证据"));service.execute(family,"order.confirm",Map.of("orderId",2,"confirmation","家属核实服务完成"));assertEquals("COMPLETED",d.one("SELECT status FROM service_order WHERE id=2").get("status"));assertEquals(60,d.count("SELECT effective_minutes FROM attendance WHERE id=?",attendance));});}
 @Test void mixedBatchUnauthorizedRollsBack(){long before=d.count("SELECT COUNT(*) FROM vital");reject(()->service.execute(admin,"vital.upload",Map.of("samples",List.of(Map.of("bindingId",1,"metricId",1,"sampleKey","batch-ok","collectedAt",LocalDateTime.now().toString(),"value",50),Map.of("bindingId",2,"metricId",2,"sampleKey","batch-no-access","collectedAt",LocalDateTime.now().toString(),"value",50)))));assertEquals(before,d.count("SELECT COUNT(*) FROM vital"));}
 @Test void loginFailureLockPersists(){for(int i=0;i<5;i++)assertThrows(Rule.class,()->auth.login("family20","wrong-password"));assertThrows(Rule.class,()->auth.login("family20",System.getenv("DEMO_PASSWORD")));assertTrue(d.count("SELECT failures FROM account WHERE username='family20'")>=5);d.update("UPDATE account SET failures=0,locked_until=NULL WHERE username='family20'");}
 @Test void unusedShiftCanBeDeleted(){rollback(()->{var manager=new Auth.User(4,"manager1","MANAGER",1,1L);long n=((Number)service.execute(manager,"shift.create",Map.of("caregiverId",1,"startsAt",LocalDateTime.now().plusDays(50).toString(),"endsAt",LocalDateTime.now().plusDays(50).plusHours(1).toString(),"capacity",2))).longValue();service.execute(manager,"shift.delete",Map.of("shiftId",n));assertEquals(0,d.count("SELECT COUNT(*) FROM shift WHERE id=?",n));});}
 @Test @Order(2147483645) void failedReassignmentRestoresPriorDispatch(){service.execute(admin,"order.assign",Map.of("orderId",2,"shiftId",2,"reason","回滚验证初次派单"));long before=d.count("SELECT id FROM v_dispatch_context WHERE active_order=2");assertThrows(RuntimeException.class,()->service.execute(admin,"order.assign",Map.of("orderId",2,"shiftId",1,"reason","故意选择不覆盖预约时间的旧班次")));assertEquals(before,d.count("SELECT id FROM v_dispatch_context WHERE active_order=2"));assertEquals(1,d.count("SELECT used_count FROM shift WHERE id=2"));service.execute(admin,"order.cancel",Map.of("orderId",2,"reason","测试结束释放名额"));d.update("UPDATE service_order SET status='PENDING' WHERE id=2");}
 @Test @Order(2147483646) void concurrentPlanCreationSerializes()throws Exception{
  var start=LocalDateTime.now().plusDays(120).withNano(0);var barrier=new CyclicBarrier(2);var pool=Executors.newFixedThreadPool(2);List<Future<Boolean>>fs=new ArrayList<>();
  for(int i=0;i<2;i++)fs.add(pool.submit(()->{barrier.await();try{new TransactionTemplate(tm).execute(s->{d.insert("INSERT INTO care_plan(assessment_id,bundle_id,caregiver_id,starts_at,ends_at) VALUES(1,1,1,?,?)",start,start.plusDays(1));return null;});return true;}catch(RuntimeException e){return false;}}));
  int success=0;for(var f:fs)if(f.get(15,TimeUnit.SECONDS))success++;pool.shutdownNow();assertEquals(1,success);d.update("UPDATE care_plan SET status='ENDED' WHERE assessment_id=1 AND starts_at=?",start);
 }
 @Test @Order(2147483647) void concurrentLastSlotOnlyOneSucceeds()throws Exception{
  d.update("UPDATE shift SET capacity=1 WHERE id=2");var o=d.one("SELECT * FROM service_order WHERE id=2");long extra=d.insert("INSERT INTO service_order(elder_id,item_id,community_id,starts_at,ends_at,address,channel,amount,created_by) SELECT elder_id,item_id,community_id,starts_at+INTERVAL 2 HOUR,ends_at+INTERVAL 2 HOUR,address,channel,amount,created_by FROM service_order WHERE id=2");
  var barrier=new CyclicBarrier(2);var pool=Executors.newFixedThreadPool(2);List<Future<Boolean>>fs=new ArrayList<>();for(long order:new long[]{2,extra})fs.add(pool.submit(()->{barrier.await();try{service.execute(admin,"order.assign",Map.of("orderId",order,"shiftId",2,"reason","并发最后名额"));return true;}catch(RuntimeException e){return false;}}));
  int success=0;for(var f:fs)if(f.get(15,TimeUnit.SECONDS))success++;pool.shutdownNow();assertEquals(1,success);assertEquals(1,d.count("SELECT used_count FROM shift WHERE id=2"));
 }
}
